library(creditratingsystem)
cases<-jsonlite::fromJSON('[{"X": [[0, 0], [1, 1]], "y": [0, 1], "model_contract": {"model_id": "heldout", "model_version": "1", "feature_order": ["x", "y"], "output_scale": "probability", "deterministic_frozen": true, "target": {"event": "default", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}, "feature_groups": {"x": ["x"], "y": ["y"]}, "permutations": [[0, 1], [1, 0]], "design": {"split": "OUT_OF_TIME", "training_end": "2022-12-31", "data_cutoff": "2024-02-01", "train_row_ids": ["train"], "train_subject_ids": ["trained"], "model_and_calibration_frozen": true, "selection_use": "FORBIDDEN", "permutation_design": "FIXED_PERMUTATIONS"}, "loss_contract": {"loss_id": "brier", "version": "1", "kind": "BRIER"}, "row_metadata": [{"row_id": "0", "subject_id": "s0", "observation_time": "2023-01-01", "target_end": "2024-01-01", "label_known_time": "2024-01-01"}, {"row_id": "1", "subject_id": "s1", "observation_time": "2023-01-01", "target_end": "2024-01-01", "label_known_time": "2024-01-01"}]}, {"X": [[0, 0], [1, 1]], "y": [0, 1], "model_contract": {"model_id": "heldout", "model_version": "1", "feature_order": ["x", "y"], "output_scale": "probability", "deterministic_frozen": true, "target": {"event": "default", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}, "feature_groups": {"x": ["x"], "y": ["y"]}, "permutations": [[0, 1], [1, 0]], "design": {"split": "OUT_OF_TIME", "training_end": "2022-12-31", "data_cutoff": "2024-02-01", "train_row_ids": ["train"], "train_subject_ids": ["trained"], "model_and_calibration_frozen": true, "selection_use": "FORBIDDEN", "permutation_design": "IID_RANDOM_PERMUTATIONS"}, "loss_contract": {"loss_id": "brier", "version": "1", "kind": "BRIER"}, "row_metadata": [{"row_id": "0", "subject_id": "s0", "observation_time": "2023-01-01", "target_end": "2024-01-01", "label_known_time": "2024-01-01"}, {"row_id": "1", "subject_id": "s1", "observation_time": "2023-01-01", "target_end": "2024-01-01", "label_known_time": "2024-01-01"}], "support_contract": {"support_id": "equal", "version": "1"}}, {"X": [[0, 0], [1, 1]], "y": [0, 1], "model_contract": {"model_id": "heldout", "model_version": "1", "feature_order": ["x", "y"], "output_scale": "probability", "deterministic_frozen": true, "target": {"event": "default", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}, "feature_groups": {"joint": ["x", "y"]}, "permutations": [[0, 1], [1, 0]], "design": {"split": "OUT_OF_TIME", "training_end": "2022-12-31", "data_cutoff": "2024-02-01", "train_row_ids": ["train"], "train_subject_ids": ["trained"], "model_and_calibration_frozen": true, "selection_use": "FORBIDDEN", "permutation_design": "IID_RANDOM_PERMUTATIONS"}, "loss_contract": {"loss_id": "brier", "version": "1", "kind": "BRIER"}, "row_metadata": [{"row_id": "0", "subject_id": "s0", "observation_time": "2023-01-01", "target_end": "2024-01-01", "label_known_time": "2024-01-01"}, {"row_id": "1", "subject_id": "s1", "observation_time": "2023-01-01", "target_end": "2024-01-01", "label_known_time": "2024-01-01"}], "support_contract": {"support_id": "equal", "version": "1"}}, {"X": [[0, 0], [1, 1]], "y": [0, 1], "model_contract": {"model_id": "heldout", "model_version": "1", "feature_order": ["x", "y"], "output_scale": "probability", "deterministic_frozen": true, "target": {"event": "default", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}, "feature_groups": {"x": ["x"], "y": ["y"]}, "permutations": [[0, 1], [1, 0]], "design": {"split": "OUT_OF_TIME", "training_end": "2022-12-31", "data_cutoff": "2024-02-01", "train_row_ids": ["train"], "train_subject_ids": ["trained"], "model_and_calibration_frozen": true, "selection_use": "FORBIDDEN", "permutation_design": "FIXED_PERMUTATIONS"}, "loss_contract": {"loss_id": "brier", "version": "1", "kind": "CUSTOM"}, "row_metadata": [{"row_id": "0", "subject_id": "s0", "observation_time": "2023-01-01", "target_end": "2024-01-01", "label_known_time": "2024-01-01"}, {"row_id": "1", "subject_id": "s1", "observation_time": "2023-01-01", "target_end": "2024-01-01", "label_known_time": "2024-01-01"}]}]',simplifyVector=FALSE);out<-list()
for(i in seq_along(cases)){
 a<-cases[[i]];a$y<-unlist(a$y);a$predictor<-function(z)z[,1]
 if(!is.null(a$support_contract))a$support_evaluator<-function(z)z[,1]==z[,2]
 if(a$loss_contract$kind=='CUSTOM')a$custom_loss<-function(y,p)2*(y-p)^2
 r<-do.call(credit_permutation_importance,a);out[[i]]<-list(value=r$value,diagnostics=r$diagnostics)
}
stopifnot(out[[1]]$value$baseline_loss==0,out[[1]]$value$groups[[1]]$mean_loss_increase==.5,out[[1]]$value$groups[[2]]$mean_loss_increase==0,is.null(out[[1]]$value$groups[[1]]$permutation_standard_error),out[[2]]$value$groups[[1]]$permutation_standard_error==.5,out[[2]]$value$groups[[1]]$support_findings[[2]]$unsupported_weight==1,out[[3]]$value$groups[[1]]$support_findings[[2]]$unsupported_weight==0,out[[4]]$value$groups[[1]]$mean_loss_increase==1)
